class Solution:
    def maxProduct(self, nums: list[int]) -> int:
        max_val = nums[0]
        min_val = nums[0]
        result = nums[0]
        for i in range(1, len(nums)):
            num = nums[i]
            if num < 0:
                max_val, min_val = min_val, max_val
            max_val = max(num, max_val * num)
            min_val = min(num, min_val * num)
            result = max(result, max_val)
        return result
